"""Browser view for interactive RIG Mission Control.

No filesystem, subprocess, scheduling, or policy logic belongs here. The page
talks only to localhost JSON endpoints exposed by mission_server.
"""

from __future__ import annotations

import json


CSS = r"""
:root{color-scheme:light dark;--bg:#f4f6f8;--panel:#fff;--panel2:#f8fafc;--ink:#111418;--muted:#6d7580;--line:#dce1e7;--accent:#465fff;--good:#0b7a55;--warn:#a86700;--bad:#b42318;--shadow:0 12px 30px rgba(20,30,50,.06)}
@media(prefers-color-scheme:dark){:root{--bg:#0b0f14;--panel:#121820;--panel2:#171e27;--ink:#edf2f7;--muted:#98a4b3;--line:#29323d;--accent:#91a1ff;--good:#68d6aa;--warn:#f2b84b;--bad:#ff8d87;--shadow:none}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}.shell{min-height:100vh;display:grid;grid-template-rows:64px 1fr}.topbar{display:flex;align-items:center;justify-content:space-between;padding:0 22px;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--panel) 92%,transparent);position:sticky;top:0;z-index:5}.brand{display:flex;align-items:center;gap:12px}.brand b{font-size:17px}.live{font:700 10px ui-monospace,SFMono-Regular,monospace;letter-spacing:.12em;color:var(--good);display:flex;gap:7px;align-items:center}.dot{width:8px;height:8px;border-radius:50%;background:var(--good);box-shadow:0 0 0 4px color-mix(in srgb,var(--good) 15%,transparent)}.layout{display:grid;grid-template-columns:350px minmax(0,1fr);min-height:0}.sidebar{border-right:1px solid var(--line);padding:16px;overflow:auto;background:var(--panel)}.main{padding:24px;overflow:auto;max-width:1500px;width:100%;margin:auto}.section-title{display:flex;align-items:center;justify-content:space-between;margin:0 0 10px;font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}.formbox{display:grid;gap:8px;padding:12px;border:1px solid var(--line);border-radius:13px;background:var(--panel2);margin-bottom:18px}.formbox textarea{min-height:68px;resize:vertical}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:7px}.field{width:100%;border:1px solid var(--line);background:var(--panel);color:var(--ink);border-radius:9px;padding:9px 10px}.btn{border:1px solid var(--line);background:var(--panel);color:var(--ink);padding:8px 11px;border-radius:9px;cursor:pointer;font-weight:650;font-size:12px}.btn:hover{border-color:var(--accent)}.btn.primary{background:var(--accent);border-color:var(--accent);color:white}.btn.danger{color:var(--bad)}.btn.good{color:var(--good)}.btn:disabled{opacity:.45;cursor:not-allowed}.list{display:grid;gap:7px;margin-bottom:18px}.item{border:1px solid var(--line);border-radius:11px;padding:10px;background:var(--panel)}.task-item{cursor:pointer}.task-item:hover,.task-item.active{border-color:var(--accent);box-shadow:var(--shadow)}.meta{display:flex;justify-content:space-between;gap:8px;color:var(--muted);font-size:10px}.name{font-size:12px;margin:6px 0 4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pill{display:inline-block;padding:2px 6px;border-radius:999px;background:var(--panel2);border:1px solid var(--line);font:650 9px ui-monospace,SFMono-Regular,monospace}.metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.metric,.card{border:1px solid var(--line);background:var(--panel);border-radius:14px;box-shadow:var(--shadow)}.metric{padding:14px}.metric .label{font-size:9px;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);font-weight:700}.metric .value{font-size:25px;font-weight:760;margin-top:5px}.metric .detail{font-size:10px;color:var(--muted);margin-top:3px}.card{padding:16px;margin-top:14px}.core{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}.core-step{border:1px solid var(--line);border-radius:10px;padding:10px;background:var(--panel2)}.core-step b{display:block;margin-top:3px}.worker{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center}.worker .status{font-weight:760}.run-index-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.run-index-issues{display:grid;gap:7px;margin-top:10px}.detail-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr);gap:14px}.headline{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.headline h2{margin:2px 0 6px;font-size:22px}.muted{color:var(--muted)}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}.progress-list{display:grid;gap:7px;margin-top:11px}.progress-row{display:grid;grid-template-columns:18px minmax(0,1fr) auto;gap:8px;align-items:center;font-size:12px}.checks{display:grid;gap:6px}.check{display:grid;grid-template-columns:18px minmax(0,1fr);gap:7px;padding:7px 0;border-bottom:1px solid var(--line);font-size:11px}.check:last-child{border:0}.ok{color:var(--good)}.warn{color:var(--warn)}.bad{color:var(--bad)}.output{white-space:pre-wrap;max-height:280px;overflow:auto;background:#0b0f14;color:#d9e1ea;border-radius:10px;padding:12px;font:11px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace}.toast{position:fixed;right:20px;bottom:20px;max-width:540px;border:1px solid var(--line);background:var(--panel);border-radius:12px;padding:12px 14px;box-shadow:0 14px 50px rgba(0,0,0,.2);display:none;z-index:10}.toast.show{display:block}.empty{padding:20px;border:1px dashed var(--line);border-radius:14px;text-align:center;color:var(--muted);font-size:11px}.tiny{font-size:10px}.queue-actions{margin-top:7px}.sep{height:1px;background:var(--line);margin:14px 0}.graph{display:grid;gap:9px;margin-top:11px}.glane{display:grid;grid-template-columns:92px minmax(0,1fr);gap:10px;align-items:start}.glane>.lname{font:700 9px ui-monospace,SFMono-Regular,monospace;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);padding-top:7px}.gnodes{display:flex;flex-wrap:wrap;gap:7px;align-items:center}.gnode{border:1px solid var(--line);border-radius:10px;padding:6px 9px;background:var(--panel2);font-size:11px;display:grid;gap:2px;min-width:0}.gnode .gk{font:650 8px ui-monospace,SFMono-Regular,monospace;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}.gnode.fanout{border-style:dashed}.gnode.member{background:var(--panel);margin-left:14px}.garrow{color:var(--muted);font-size:12px}.gnote{font-size:10px;color:var(--muted);margin-top:5px}
@media(max-width:1050px){.layout{grid-template-columns:1fr}.sidebar{border-right:0;border-bottom:1px solid var(--line);max-height:600px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.run-index-summary{grid-template-columns:1fr}.detail-grid{grid-template-columns:1fr}.core{grid-template-columns:1fr}.worker{grid-template-columns:1fr}.twocol{grid-template-columns:1fr}}
"""


JS_TEMPLATE = r"""
const CSRF=__CSRF__;
let selected=null,snapshot=null;
const $=(q)=>document.querySelector(q);
const esc=(s)=>String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m]));
async function api(path,options={}){const headers={'Accept':'application/json',...(options.headers||{})};if(options.method==='POST'){headers['Content-Type']='application/json';headers['X-RIG-CSRF']=CSRF;}const r=await fetch(path,{...options,headers});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||d.stderr||`HTTP ${r.status}`),{data:d});return d;}
function toast(title,data){const el=$('#toast');const raw=data?((data.stdout||'')+(data.stderr?`\n${data.stderr}`:'')+(data.queued?.stdout?`\n${data.queued.stdout}`:'')):'';el.innerHTML=`<b>${esc(title)}</b>${raw?`<pre class="output">${esc(raw)}</pre>`:''}`;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),8000);}
function metric(label,value,detail=''){return `<div class="metric"><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div><div class="detail">${esc(detail)}</div></div>`}
function renderOverview(){const o=snapshot.operations,p=snapshot.production,u=o.token_usage||{},tokens=u.prompt_tokens!=null?(u.prompt_tokens||0)+(u.completion_tokens||0):'unmeasured';$('#metrics').innerHTML=metric('active tasks',o.tasks_active,`${o.tasks_total} total`+(o.tasks_unreadable_note?` · ${o.tasks_unreadable_note}`:''))+metric('gate failures',(o.gate_counts||{}).failed||0,'recorded history')+metric('RIG tokens',Object.keys(u).length?tokens:'unmeasured',Object.keys(u).length?`${u.calls||0} metered calls`:'provider may not expose usage')+metric('incident rate',p.incident_rate_pct==null?'unmeasured':`${p.incident_rate_pct}%`,`${p.incidents} / ${p.outcomes_recorded} outcomes`)+metric('outcome coverage',p.outcome_coverage_pct==null?'unmeasured':`${p.outcome_coverage_pct}%`,`${p.outcomes_recorded} / ${p.accepted_tasks} accepted`);$('#core').innerHTML=snapshot.core.map((s,i)=>`<div class="core-step"><span class="mono muted">0${i+1}</span><b>${esc(s.label)}</b><span class="muted tiny">${esc(s.meaning)}</span></div>`).join('');}
function renderRunIndex(){
  const index=snapshot&&snapshot.run_index,rows=index&&Array.isArray(index.rows)?index.rows:[];
  if(!index||!rows.length){$('#run-index').innerHTML='<div class="empty">No indexed runs yet.</div>';return;}
  const projects=Array.isArray(index.projects)?index.projects:[],runTotal=index.total??rows.length,details=[];
  if(Number(index.unreadable)>0)details.push(`${index.unreadable} unreadable record${Number(index.unreadable)===1?'':'s'}`);
  if(index.truncated)details.push('history truncated');
  const verifiers=Object.entries(index.by_verifier||{}),verifierRows=verifiers.length?verifiers.map(([provider,raw])=>{
    const item=raw||{};
    return `<div class="item"><div class="meta"><span class="mono">${esc(provider)}</span><span>${esc(item.runs??0)} run${Number(item.runs)===1?'':'s'} represented</span></div><div class="name">Recorded verdicts, not a quality score</div><div class="muted tiny">not-OK verdicts: ${esc(item.not_ok??0)} · unknown verdicts: ${esc(item.unknown??0)} · OK verdicts: ${esc(item.ok??0)}</div></div>`;
  }).join(''):'<div class="empty">No verifier verdicts recorded.</div>';
  const issues=Object.entries(index.by_issue||{}),issueRows=issues.length?issues.map(([ref,raw])=>{
    const item=raw||{},touchedProjects=Array.isArray(item.projects)?item.projects:[],sessions=Array.isArray(item.sessions)?item.sessions:[];
    return `<div class="item"><div class="meta"><span class="mono">${esc(ref)}</span><span>${esc(item.runs??0)} run${Number(item.runs)===1?'':'s'}</span></div><div class="name">last final: ${esc(item.last_final??'—')}</div><div class="muted tiny">projects: ${touchedProjects.length?touchedProjects.map(project=>esc(project)).join(', '):'—'}</div><div class="muted tiny">sessions: ${sessions.length?sessions.map(session=>esc(session)).join(', '):'—'}</div></div>`;
  }).join(''):'<div class="empty">No issue-linked runs.</div>';
  $('#run-index').innerHTML=`<div class="run-index-summary">${metric('projects',projects.length,'cross-project history')}${metric('runs',runTotal,details.join(' · '))}</div><div class="run-index-issues run-index-verifiers"><div class="section-title">Recorded verifier verdicts</div><div class="muted tiny">These are verdict counts over submitted runs, not pass rates, reviewer detection rates, or quality scores. Measured reviewer detection lives in <span class="mono">/rig:drill</span>.</div>${verifierRows}</div><div class="run-index-issues">${issueRows}</div>`;
}
function renderTasks(){const tasks=snapshot.live.tasks;$('#task-list').innerHTML=tasks.length?tasks.map(t=>`<div class="item task-item ${selected===t.task_id?'active':''}" data-id="${esc(t.task_id)}"><div class="meta"><span class="pill">${esc(t.status)}</span><span>${esc(t.gate)}</span></div><div class="name">${esc(t.input)}</div><div class="meta"><span>${esc(t.task_type)}</span><span class="mono">${esc(t.task_id)}</span></div></div>`).join(''):'<div class="empty">No workbench tasks yet.</div>';document.querySelectorAll('.task-item').forEach(el=>el.onclick=()=>selectTask(el.dataset.id));}
function renderJobs(){const j=snapshot.jobs,w=j.worker||{},items=j.items||[];$('#worker').innerHTML=`<div><span class="pill">WORKER</span></div><div><div class="status ${w.status==='failed'||w.status==='stale'?'bad':w.status==='running'?'ok':''}">${esc(w.status||'idle')}</div><div class="muted tiny">${esc(w.provider||'—')} → ${esc(w.verifier_provider||'—')} · pid ${esc(w.pid||'—')} · queued ${(j.counts||{}).queued||0} · running ${(j.counts||{}).running||0}</div></div><button class="btn" onclick="toggleWorkerLog()">Worker log</button>`;$('#queue-list').innerHTML=j.queue_error?`<div class="empty bad">${esc(j.queue_error)}</div>`:items.length?items.map(x=>`<div class="item"><div class="meta"><span class="pill">${esc(x.status||'?')}</span><span class="mono">#${esc(x.id)}</span></div><div class="name">${esc(x.task||'')}</div>${x.note?`<div class="muted tiny">${esc(x.note)}</div>`:''}${(x.depends_on||[]).length?`<div class="muted tiny">depends on ${x.depends_on.map(d=>'#'+esc(d)).join(', ')} · ${esc(x.dependency_policy||'')}</div>`:''}${x.dependency_note?`<div class="muted tiny warn">${esc(x.dependency_note)}</div>`:''}${x.status==='failed'||x.status==='running'||x.status==='cancelled'?`<div class="queue-actions"><button class="btn" onclick="retryJob('${esc(x.id)}')">Retry</button></div>`:''}</div>`).join(''):'<div class="empty">Queue empty. Start an autonomous run.</div>';$('#worker-log').textContent=j.worker_log_tail||'No worker log yet.';}
function toggleWorkerLog(){const e=$('#worker-log-card');e.hidden=!e.hidden;}
function renderGraph(g){if(!g||g.error)return `<div class="empty">${esc((g&&g.error)||'No graph.')}</div>`;const byLane={};(g.nodes||[]).forEach(n=>{(byLane[n.lane]=byLane[n.lane]||[]).push(n)});const cls=(s)=>s==='passed'?'ok':s==='failed'?'bad':s==='warning'?'warn':'';const chip=(n)=>`<div class="gnode ${n.kind==='fanout'?'fanout':''} ${n.kind==='reviewer'?'member':''}" title="${esc(n.detail||'')}"><span class="gk">${esc(n.kind)}</span><span><span class="${cls(n.status)}">${statusIcon(n.status)}</span> ${esc(n.label)}</span>${n.verdict?`<span class="muted tiny">${esc(n.verdict)}</span>`:''}</div>`;const lanes=(g.lanes||[]).filter(l=>byLane[l]&&byLane[l].length).map(l=>`<div class="glane"><div class="lname">${esc(l)}</div><div class="gnodes">${byLane[l].map((n,i)=>(i?'<span class="garrow">›</span>':'')+chip(n)).join('')}</div></div>`).join('');const pv=g.providers||{};const slot=(k)=>{const v=pv[k]||{};return `${esc(k)}: ${v.observed?esc(v.id||v.model||'recorded'):'not recorded'}`};return lanes+`<div class="gnote">${esc(g.recipe&&g.recipe.name||'?')} · structure from ${esc(g.recipe&&g.recipe.structure_resolved_from||'?')} · provider ${slot('execution')} / ${slot('verification')}</div>`;}
function statusIcon(s){return s==='passed'?'✓':s==='failed'?'✕':s==='warning'?'!':s==='running'?'●':'○'}
async function selectTask(id){selected=id;renderTasks();const d=await api(`/api/tasks/${encodeURIComponent(id)}`);renderDetail(d);}
function renderDetail(d){const t=d.task||{},a=d.acceptance||{},steps=(d.steps||{}).steps||[],checks=a.checks||[],out=d.outcome;let page=`<div class="card"><div class="headline"><div><span class="pill">${esc(t.status||'?')}</span><h2>${esc(t.input||t.task_id)}</h2><div class="muted mono">${esc(t.task_id)} · ${esc(t.task_type||'?')} ${t.recipe?`· ${esc(t.recipe)}`:''}</div></div><div class="mono muted">gate: ${esc(a.status||'unmeasured')}</div></div><div class="actions"><button class="btn" onclick="showDiff()">View Diff</button><button class="btn good" onclick="acceptTask()">Accept</button><button class="btn danger" onclick="discardTask()">Discard</button><button class="btn" onclick="approval('grant')">Approve</button><button class="btn" onclick="approval('deny')">Deny</button>${t.status==='accepted'?'<button class="btn" onclick="outcome(\'ok\')">Outcome: OK</button><button class="btn danger" onclick="outcome(\'incident\')">Outcome: Incident</button>':''}</div></div>`;page+=`<div class="card"><div class="section-title">Resolved workflow</div><div class="graph">${renderGraph(d.graph)}</div></div>`;page+=`<div class="detail-grid"><div class="card"><div class="section-title">Execution</div><div class="progress-list">${steps.length?steps.map(s=>`<div class="progress-row"><span class="${s.status==='passed'?'ok':s.status==='failed'?'bad':''}">${statusIcon(s.status)}</span><span>${esc(s.name)}</span><span class="mono muted">${esc(s.status)}</span></div>`).join(''):'<span class="muted">No step telemetry.</span>'}</div></div><div class="card"><div class="section-title">Acceptance</div><div class="checks">${checks.length?checks.map(c=>`<div class="check"><span class="${c.status==='passed'?'ok':c.status==='failed'?'bad':'warn'}">${statusIcon(c.status)}</span><span><b>${esc(c.name)}</b>${c.detail?`<br><span class="muted">${esc(c.detail)}</span>`:''}</span></div>`).join(''):'<span class="muted">Unmeasured.</span>'}</div>${out?`<div class="section-title" style="margin-top:14px">Production outcome</div><div>${esc(out.status)} <span class="muted">${esc(out.note||'')}</span></div>`:''}</div></div>`;page+=renderHandoff(d.handoff);$('#detail').innerHTML=page;}
function renderHandoff(notes){
  // Hand-off notes (#548): what this run wrote for a later run touching the named
  // artifacts. Every field is text somebody typed, so all of it goes through esc(). The
  // list is what was recorded, in the order it was recorded; nothing here is a status.
  const list=Array.isArray(notes)?notes:[];
  const rows=list.length?list.map(n=>{const about=Array.isArray(n.about)?n.about:[];return `<div class="item"><div class="meta"><span class="mono muted">${esc(n.recorded_at||'')}</span>${about.length?`<span class="mono">about: ${about.map(a=>esc(a)).join(', ')}</span>`:''}</div><div class="name">${esc(n.text||'')}</div></div>`;}).join(''):'<div class="empty">No hand-off notes.</div>';
  return `<div class="card"><div class="section-title">Hand-off notes</div><div class="muted tiny">Written by this run for a later one, about the artifacts they name. Records, not messages.</div>${rows}</div>`;
}
async function perform(action,payload={}){if(!selected)return;try{const d=await api(`/api/tasks/${encodeURIComponent(selected)}/${action}`,{method:'POST',body:JSON.stringify(payload)});toast(`${action}: completed`,d);await refresh();await selectTask(selected);}catch(e){toast(`${action}: refused`,e.data||{stderr:e.message});}}
async function showDiff(){try{const d=await api(`/api/tasks/${encodeURIComponent(selected)}/diff`);toast('Diff',d);}catch(e){toast('Diff failed',e.data||{stderr:e.message});}}
async function acceptTask(){if(confirm('Accept this task? RIG Core will re-check gate, approvals, policy and worktree state.'))await perform('accept');}
async function discardTask(){const c=prompt(`Destructive action. Type the exact task id to discard:\n${selected}`);if(c===selected)await perform('discard',{confirm:c});}
async function approval(decision){const note=prompt(`${decision==='grant'?'Approval':'Denial'} note (optional):`,'')??'';await perform('approval',{decision,note});}
async function outcome(status){const note=prompt(`Record production outcome: ${status}\nNote (optional):`,'')??'';await perform('outcome',{status,note});}
async function newTask(){const input=$('#new-input').value.trim(),task_type=$('#new-type').value;if(!input)return;try{const d=await api('/api/tasks',{method:'POST',body:JSON.stringify({input,task_type})});toast('Task registered',d);$('#new-input').value='';await refresh();}catch(e){toast('Task creation refused',e.data||{stderr:e.message});}}
async function startJob(){const task=$('#job-input').value.trim();if(!task)return;const payload={task,provider:$('#job-provider').value,verifier_provider:$('#job-verifier').value,max_parallel:Number($('#job-parallel').value)};try{const d=await api('/api/jobs',{method:'POST',body:JSON.stringify(payload)});toast('Autonomous run queued',d);$('#job-input').value='';await refresh();}catch(e){toast('Autonomous run refused',e.data||{stderr:e.message});}}
async function retryJob(id){try{const d=await api(`/api/jobs/${id}/retry`,{method:'POST',body:'{}'});toast(`Queue #${id} retried`,d);await refresh();}catch(e){toast('Retry refused',e.data||{stderr:e.message});}}
async function refresh(){try{snapshot=await api('/api/snapshot');$('#live-state').textContent='LIVE';renderOverview();renderRunIndex();renderTasks();renderJobs();if(!selected&&snapshot.live.tasks.length){selected=snapshot.live.tasks[0].task_id;renderTasks();await selectTask(selected);}const old=$('#new-type').value;$('#new-type').innerHTML=snapshot.live.task_types.map(x=>`<option>${esc(x)}</option>`).join('');if(snapshot.live.task_types.includes(old))$('#new-type').value=old;const providers=snapshot.jobs.providers||[];for(const id of ['#job-provider','#job-verifier']){const el=$(id),v=el.value;el.innerHTML=providers.map(x=>`<option>${esc(x)}</option>`).join('');if(providers.includes(v))el.value=v;}if(!$('#job-provider').dataset.init){$('#job-provider').value=providers.includes('rig')?'rig':providers[0];$('#job-verifier').value=providers.includes('codex')?'codex':($('#job-provider').value||providers[0]);$('#job-provider').dataset.init='1';}}catch(e){$('#live-state').textContent='OFFLINE';}}
$('#new-button').onclick=newTask;$('#job-button').onclick=startJob;$('#refresh').onclick=refresh;refresh();setInterval(refresh,2000);
"""


def interactive_html(csrf_token: str) -> str:
    js = JS_TEMPLATE.replace("__CSRF__", json.dumps(csrf_token))
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RIG Mission Control · Live</title><style>{CSS}</style></head><body><div class="shell"><div class="topbar"><div class="brand"><b>RIG Mission Control</b><span class="live"><span class="dot"></span><span id="live-state">CONNECTING</span></span></div><button class="btn" id="refresh">Refresh</button></div><div class="layout"><aside class="sidebar"><div class="section-title">Autonomous AI Run</div><div class="formbox"><textarea class="field" id="job-input" placeholder="What should RIG execute autonomously?"></textarea><div class="twocol"><select class="field" id="job-provider"></select><select class="field" id="job-verifier"></select></div><select class="field" id="job-parallel"><option value="1">1 parallel</option><option value="2">2 parallel</option><option value="3">3 parallel</option><option value="4">4 parallel</option></select><button class="btn primary" id="job-button">Start AI Run</button><div class="muted tiny">Durable: persisted in .rig/queue.json. Closing this page does not stop the detached worker.</div></div><div class="section-title">AI Queue</div><div id="queue-list" class="list"></div><div class="sep"></div><div class="section-title">Register Only</div><div class="formbox"><textarea class="field" id="new-input" placeholder="Register an isolated task without starting a model."></textarea><select class="field" id="new-type"></select><button class="btn" id="new-button">Register isolated task</button></div><div class="section-title">Workbench Runs</div><div id="task-list" class="list"></div></aside><main class="main"><div class="card worker" id="worker"></div><div class="card" id="worker-log-card" hidden><div class="section-title">Detached worker log</div><pre class="output" id="worker-log"></pre></div><div class="section-title" style="margin-top:20px">RIG Core</div><div class="core" id="core"></div><div class="section-title" style="margin-top:20px">Now</div><div class="metrics" id="metrics"></div><div class="section-title" style="margin-top:20px">Run index</div><div id="run-index"></div><div id="detail" style="margin-top:20px"><div class="empty">Select a workbench task. Autonomous queue items appear here after the provider creates their isolated RIG task.</div></div></main></div></div><div class="toast" id="toast"></div><script>{js}</script></body></html>"""
